/**
 * The data behind the two CSV exports the TS front builds in the browser (file-saver):
 * the members list (MembersTableAndActions.tsx) and the vendor's distributions
 * (vendorDistribsCsv.utils.ts). The CSV file itself (columns order, ";" separator, UTF-8 BOM,
 * file name) is generated by browser code and is not tested here; the queries are the ones the front sends
 * (specs/06-payments/reports-exports.md PAY-RPT-011, PAY-RPT-012).
 */
import { test, expect } from '../../src/fixtures.js';
import { queryOne } from '../../src/db/client.js';
import * as make from '../../src/factories/index.js';
import { subscribeConst, subscribeVar } from '../../src/flows.js';

// members.gql.ts getMembersOfGroupByListType
const MEMBERS = `query($listType: String!, $groupId: Int!, $data: String) {
  getUserListInGroupByListType(listType: $listType, groupId: $groupId, data: $data) {
    id firstName lastName firstName2 lastName2 city zipCode address1 address2 email phone email2 phone2
  }
}`;
// vendorDashboard.gql GetVendorDistributionsCsv
const VENDOR_CSV = `query($vendorId: Int!, $fromDate: DateTime) {
  vendor(id: $vendorId) {
    id
    allCatalogs { id name group { id name } products { id name active } }
    allDistributions(fromDate: $fromDate) { group { id } distributions { id date catalog { id } userOrders { quantity product { id } } } }
  }
}`;

test.describe('the members list as the CSV export reads it (PAY-RPT-011)', () => {
  test('a membership manager gets the contact fields of every member of the list', { tag: ['@PAY-RPT-011'] }, async ({ app, as }) => {
    const s = await make.amapScenario();
    const second = await make.user({ firstName: 'Léa', lastName: 'Duo', email: 'lea@camap.test', email2: 'lea2@camap.test', firstName2: 'Paul', lastName2: 'Duo', phone: '0611223344' });
    await make.userGroup({ user: second, group: s.group });
    const mm = await as(s.users.membershipManager);

    const res = await app.graphql<{ getUserListInGroupByListType: Record<string, unknown>[] }>(mm.request, MEMBERS, { listType: 'all', groupId: s.group.id, data: null });

    expect(res.errors).toBeNull();
    const rows = res.data!.getUserListInGroupByListType;
    expect(rows).toHaveLength(7);
    expect(Object.keys(rows[0])).toEqual(['id', 'firstName', 'lastName', 'firstName2', 'lastName2', 'city', 'zipCode', 'address1', 'address2', 'email', 'phone', 'email2', 'phone2']);
    expect(rows.find((r) => r.id === second.id)).toMatchObject({
      firstName: 'Léa',
      lastName: 'Duo',
      firstName2: 'Paul',
      lastName2: 'Duo',
      email: 'lea@camap.test',
      email2: 'lea2@camap.test',
      phone: '0611223344',
    });
  });

  test('a plain member reads the same list, emails and phones included (UND-029, characterised)', { tag: ['@PAY-RPT-011'] }, async ({ app, as, anon }) => {
    const s = await make.amapScenario();
    const m = await as(s.users.member);

    const res = await app.graphql<{ getUserListInGroupByListType: { email: string }[] }>(m.request, MEMBERS, { listType: 'all', groupId: s.group.id, data: null });
    const visitor = await app.graphql(anon.request, MEMBERS, { listType: 'all', groupId: s.group.id, data: null });

    expect(res.errors).toBeNull();
    expect(res.data!.getUserListInGroupByListType.map((r) => r.email)).toContain('coordinator@camap.test');
    expect(visitor.data).toBeNull();
  });
});

test.describe('the vendor distributions as the CSV export reads them (PAY-RPT-012)', () => {
  test('the vendor gets its catalogs with their products, and the quantities ordered per distribution', { tag: ['@PAY-RPT-012'] }, async ({ app, as }) => {
    const s = await make.amapScenario();
    const [e6] = s.products.var;
    const m1 = await as(s.users.member);
    const m2 = await as(s.users.member2);
    await subscribeConst(app, m1.request, s, s.users.member.id, { quantity: 2 });
    await subscribeConst(app, m2.request, s, s.users.member2.id);
    const sub = await subscribeVar(app, m1.request, s, s.users.member.id);
    await app.api.subscription.updateOrders(m1.request, sub.id, [{ id: s.distributions[1].var.id, orders: [{ productId: e6.id, qty: 3 }] }]);
    await make.product({ catalog: s.varCatalog, name: 'Produit retiré', active: false });
    const vendor = await as(s.users.vendor);
    const vendorId = (await queryOne<{ id: number }>('SELECT id FROM Vendor LIMIT 1'))!.id;

    const res = await app.graphql<any>(vendor.request, VENDOR_CSV, { vendorId, fromDate: null });

    expect(res.errors).toBeNull();
    const v = res.data!.vendor;
    // one row per product in the CSV, inactive ones are dropped by the front, which needs the flag
    expect(v.allCatalogs.map((c: any) => [c.name, c.group.name])).toEqual(
      expect.arrayContaining([['Légumes (contrat AMAP)', 'AMAP des Tests'], ['Œufs (contrat variable)', 'AMAP des Tests']]),
    );
    const varCatalog = v.allCatalogs.find((c: any) => c.id === s.varCatalog.id);
    expect(varCatalog.products.map((p: any) => [p.name, p.active]).sort()).toEqual([['Boîte de 12 œufs', true], ['Boîte de 6 œufs', true], ['Produit retiré', false]]);
    // quantities per distribution and product (summed by the front over the orders of a distribution)
    const dists = v.allDistributions.flatMap((x: any) => x.distributions);
    expect(dists).toHaveLength(8);
    const qty = (distribId: number, productId: number) =>
      dists.find((d: any) => d.id === distribId).userOrders.filter((o: any) => o.product.id === productId).reduce((n: number, o: any) => n + o.quantity, 0);
    expect(qty(s.distributions[0].const.id, s.products.const[0].id)).toBe(3); // 2 + 1
    expect(qty(s.distributions[1].var.id, e6.id)).toBe(3);
    expect(qty(s.distributions[0].var.id, e6.id)).toBe(0);
  });
});
